const produkty = [
  { nazwa: "Kubek", cena: 25, dostepny: true },
  { nazwa: "Laptop", cena: 3000, dostepny: true },
  { nazwa: "Notes", cena: 15, dostepny: false }
];

console.log(produkty.filter(p => p.dostepny && p.cena < 200));
// [{ nazwa: 'Kubek', cena: 25, dostepny: true }]

function sprawdzPusty(tablicaWynikow) {
  if (tablicaWynikow.length === 0) {
    return "brak wynikow";
  }
  return `znaleziono ${tablicaWynikow.length} wynikow`;
}

const temperatury = [15, 22, 8, 30];
console.log(sprawdzPusty(temperatury.filter(t => t > 100))); // "brak wynikow"
console.log(sprawdzPusty(temperatury.filter(t => t > 10)));  // "znaleziono 3 wynikow"

